from common import *
import io
m=load(); out=io.StringIO()
def P(*a): print(*a,file=out)
P("# Paper 03 — AHRF primary care supply analyses (public data only)\n")
P("Generated by `p03b.py` 2026-11-27. Exposure: primary care physicians (MD + DO, non-federal, patient care, excluding residents; AHRF 2024-25, 2023 counts, AMA masterfile) per 10,000 population (Census 2023), and primary-care HPSA code (AHRF 2025). Outcomes: CHR supplement (25 Mar 2026) age-adjusted premature mortality (<75), 2021-23, overall and race-specific (published counties only). Covariates: CHR 2025 child poverty, uninsured, % Black, RUCC 2023.\n")
m['pcp10k']=m.ahrf_pcp_total23/m.ahrf_pop23*1e4
m['pov10']=m.child_poverty/10; m['black10']=m.pct_black_nh/10
P(f"Statewide: {int(m.ahrf_pcp_total23.sum())} primary care physicians (MD+DO, excl. residents) for {int(m.ahrf_pop23.sum()):,} residents = {m.ahrf_pcp_total23.sum()/m.ahrf_pop23.sum()*1e4:.1f} per 10k. Counties with 0 PCP: {(m.ahrf_pcp_total23==0).sum()}; with <3 PCP per 10k: {(m.pcp10k<3).sum()}. Correlation of AHRF PCP/10k with CHR PCP rate: Spearman rho = {spearman(m.pcp10k,m.pcp_per100k)[1]:.2f}. Primary-care HPSA codes (0/1/2): {m.ahrf_hpsa_prim25.value_counts().sort_index().to_dict()}.\n")
P("## A. Spearman: PCP supply vs premature mortality by race\n")
rows=[]
for y,l in [('prem_mort_agadj','All'),('prem_mort_white','White'),('prem_mort_black','Black'),('life_exp','Life expectancy (all)'),('prev_hosp_stays','Preventable hospital stays (Medicare)')]:
    n,r,p=spearman(m.pcp10k,m[y]); rows.append([l,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','n counties','rho (PCP per 10k)','p']).to_markdown(index=False,floatfmt='.3f')); P()
P("## B. OLS (HC3) of premature mortality per 100k on PCP/10k, adjusted for child poverty/10, uninsured, %Black/10, nonmetro\n")
rows=[]
for y,l in [('prem_mort_agadj','All'),('prem_mort_white','White'),('prem_mort_black','Black')]:
    xs=['pcp10k','pov10','unins','nonmetro'] + (['black10'] if y=='prem_mort_agadj' else [])
    m['unins']=m.uninsured_pct
    mod,t,n=ols(m,y,xs)
    r=t.loc['pcp10k']; rows.append([l,n,r.coef,f"{r.ci_lo:.1f} to {r.ci_hi:.1f}",r.p,t.loc['pov10','coef'],f"{t.loc['pov10','ci_lo']:.1f} to {t.loc['pov10','ci_hi']:.1f}",t.loc['pov10','p'],mod.rsquared])
P(pd.DataFrame(rows,columns=['Outcome','n','PCP/10k coef','95% CI','p','Child poverty/10 coef','95% CI ','p ','R2']).to_markdown(index=False,floatfmt='.3g')); P()
P("## C. WLS (weights = county population) for the same models\n")
rows=[]
for y,l in [('prem_mort_agadj','All'),('prem_mort_white','White'),('prem_mort_black','Black')]:
    xs=['pcp10k','pov10','unins','nonmetro'] + (['black10'] if y=='prem_mort_agadj' else [])
    d=m[[y]+xs+['population']].dropna(); w=sm.WLS(d[y],sm.add_constant(d[xs]),weights=d.population).fit(cov_type='HC3')
    ci=w.conf_int(); rows.append([l,len(d),w.params['pcp10k'],f"{ci.loc['pcp10k',0]:.1f} to {ci.loc['pcp10k',1]:.1f}",w.pvalues['pcp10k'],w.params['pov10'],w.pvalues['pov10']])
P(pd.DataFrame(rows,columns=['Outcome','n','PCP/10k coef','95% CI','p','Child poverty/10 coef','p ']).to_markdown(index=False,floatfmt='.3g')); P()
P("## D. Black-White gap (age-adjusted premature mortality, Black minus White) vs PCP supply and context\n")
m['gap']=m.prem_mort_black-m.prem_mort_white
rows=[]
for x,l in [('pcp10k','PCP per 10k (AHRF)'),('ahrf_hpsa_prim25','Primary-care HPSA code'),('child_poverty','Child poverty %'),('pct_black_nh','% Black NH'),('segregation_bw','B/W segregation')]:
    n,r,p=spearman(m[x],m.gap); rows.append([l,n,r,p])
P(pd.DataFrame(rows,columns=['Predictor','n counties','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
mod,t,n=ols(m,'gap',['pcp10k','pov10','nonmetro','segregation_bw']); P(f"OLS gap ~ PCP/10k + child poverty/10 + nonmetro + segregation (n={n}, R2={mod.rsquared:.2f})\n"); P(t.round(3).to_markdown()); P()
P("## E. Primary-care HPSA code vs outcomes (medians)\n")
g=m.groupby('ahrf_hpsa_prim25').agg(n=('prem_mort_agadj','size'),premature_mortality=('prem_mort_agadj','median'),diabetes_pct=('pl_diabetes_pl','median'),prev_hosp=('prev_hosp_stays','median')).round(1)
P(g.to_markdown()); P()
P("## F. Chronic-disease prevalence vs PCP supply (Spearman; PLACES BRFSS 2023 model-based; descriptive due to MRP circularity)\n")
rows=[]
for y,l in [('pl_diabetes_pl','Diabetes'),('pl_bphigh','High blood pressure'),('pl_chd','CHD'),('pl_stroke','Stroke')]:
    n,r,p=spearman(m.pcp10k,m[y]); rows.append([l,n,r,p])
P(pd.DataFrame(rows,columns=['Outcome','n','rho','p']).to_markdown(index=False,floatfmt='.3f')); P()
m[['fips','county','population','nonmetro','dra_county','ahrf_pcp_total23','pcp10k','ahrf_hpsa_prim25','prem_mort_agadj','prem_mort_white','prem_mort_black','life_exp','child_poverty','uninsured_pct','pct_black_nh']].to_csv('results/p03/p03b_county_dataset.csv',index=False)
open('results/p03/p03b_results.md','w').write(out.getvalue()); print(out.getvalue())
